def transform(g):
    h, w = len(g), len(g[0])
    blocks = []
    for r in range(h - 2):
        for c in range(w - 2):
            v = g[r][c]
            if not v or (r and g[r-1][c] == v) or (c and g[r][c-1] == v):
                continue
            if all(g[i][j] == v for i in range(r, r + 3) for j in range(c, c + 3)):
                blocks.append((r + 1, c + 1, v))
    out = [row[:] for row in g]
    for r, c, v in blocks:
        for j in range(w): out[r][j] = v
        for i in range(h): out[i][c] = v
    for r, c, v in blocks:
        for rr, cc, vv in blocks:
            if v != vv: out[r][cc] = 0
    return out
